import test from 'node:test';import assert from 'node:assert/strict';import {validatePrototypeMutation} from './prototype-policy.js';
const base=()=>({school:{name:'IAE'},settings:{},routes:[],levels:[],staff:[],permissions:{},students:[{id:'e1',titulares:['p1']}],persons:[{id:'p1'}],authorizations:[],requests:[],notifications:[],chats:{},chatState:{},log:[],busTrips:{}});const parent={id:'parent-carlos',role:'parent',prototypeIdentity:{personId:'p1'}};
test('parent cannot overwrite school or staff state',()=>{const a=base(),b=structuredClone(a);b.school.name='attacker';assert.throws(()=>validatePrototypeMutation(a,b,parent),/forbidden_prototype_field:school/)});
test('parent can add own request but not another guardian request',()=>{const a=base(),b=structuredClone(a);b.requests.push({id:'r1',requestedBy:'p1',status:'pendiente'});assert.equal(validatePrototypeMutation(a,b,parent),true);const c=structuredClone(a);c.requests.push({id:'r2',requestedBy:'p2',status:'pendiente'});assert.throws(()=>validatePrototypeMutation(a,c,parent),/forbidden_parent_request_owner/)});
test('reception can approve but gate can only mark an approved request retired',()=>{const a=base();a.requests=[{id:'r1',requestedBy:'p1',status:'pendiente'}];const approved=structuredClone(a);approved.requests[0].status='aprobada';assert.equal(validatePrototypeMutation(a,approved,{role:'reception'}),true);assert.throws(()=>validatePrototypeMutation(a,approved,{role:'gate'}),/forbidden_gate_request_change/);const retired=structuredClone(approved);retired.requests[0].status='retirado';assert.equal(validatePrototypeMutation(approved,retired,{role:'gate'}),true)});
test('server identity bindings distinguish the two guardians',async()=>{const {connectedSeed}=await import('./seed.js');const s=connectedSeed();assert.deepEqual(s.users.find(x=>x.id==='parent-carlos').prototypeIdentity,{personId:'p1',phoneId:'p1'});assert.deepEqual(s.users.find(x=>x.id==='parent-ana').prototypeIdentity,{personId:'p2',phoneId:'p2'})});
